import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class Probe {
    static int fails = 0;
    static void check(String name, String input, Safelist sl) {
        String once = Jsoup.clean(input, sl);
        String twice = Jsoup.clean(once, sl);
        boolean stable = once.equals(twice);
        String reparsed = Jsoup.clean(Jsoup.parse(once).body().html(), sl);
