import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class Probe {
    static final String Base = "https://example.com/a/b";
    static Safelist saf = Safelist.relaxed().addAttributes(":all", "style");
    static String clean(String html) {
        Document dirty = Jsoup.parseBodyFragment(html, Base);
        return new Cleaner(saf).clean(dirty).body().html();
    }
    public static void main(String[] args) {
        String[] cases = {
            "<div style=\"--x: a:b\">x</div>",
            "<div style=\"--x: {'a': 1}; color:red\">x</div>",
            "<div style=\"--x: url(javascript:1); color:red\">x</div>",
            "<div style=\"--x: fn(1, 2), 's;t:r'\">x</div>",
            "<div style=\"--x: \\\\74 est\">x</div>",
            "<div style=\"transition: color 0.2s; background: url(http://example.com/x.png)\">x</div>",
            "<div style=\"content: '12:30'\">x</div>",
            "<div style=\"--x: ;color:red\">x</div>",
            "<div style=\"--x: 1; --x: 2\">x</div>",
            "<div style=\"--x: @media { }\">x</div>",
            "<div style=\"--x: expression(1)\">x</div>",
        };
        for (String c : cases) System.out.println(c + "  =>  " + clean(c));
    }
}

