import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class P3 {
    static Safelist sl = Safelist.relaxed().addTags("pre","code","textarea").addAttributes(":all","class","id");
    static void t(String name, String in) {
        String o1 = Jsoup.clean(in, sl);
        String o2 = Jsoup.clean(o1, sl);
        String rt = Jsoup.parse(o1).body().text();
        System.out.println(name);
        System.out.println("  in =[" + in.replace("\n","\\n").replace("\t","\\t") + "]");
        System.out.println("  o1 =[" + o1.replace("\n","\\n").replace("\t","\\t") + "]");
        System.out.println("  o2 =[" + o2.replace("\n","\\n").replace("\t","\\t") + "] stable=" + o1.equals(o2));
        System.out.println("  text after reparse=[" + rt.replace("\n","\\n").replace("\t","\\t") + "]");
    }
    public static void main(String[] x) {
        // inline siblings at body level, no whitespace between
        t("inline-body", "<a href='http://a/'>A</a><script>d</script><a href='http://b/'>B</a>");
        // inline inside p with unsafe wrapper dropped
        t("inline-drop", "<p>foo <span onclick=x>bar</span> baz</p>");
        // unsafe element containing inline safe nodes, inside paragraph
        t("hoist-inline", "<p>a <b onclick=1><i>safe</i> tail</b> c</p>");
        // two anchors directly adjacent inside p, script between
        t("anchors-p", "<p><a href='http://a/'>A</a><script>x</script><a href='http://b/'>B</a></p>");
        // pre adjacent to script then text
        t("pre-adj", "<pre>a</pre><script>x</script>after");
        // code newlines
        t("code-nl", "<code>line1\nline2\n\nline3</code>");
        // whitespace-only around dropped nodes
        t("ws-drop", "<p>x</p> \n <script>y</script> <p>z</p>");
        // safe element child of rejected a?
        t("a-rel", "<p><a href='javascript:alert(1)'><b>click</b></a></p>");
        // nested rejected with block hoisting across siblings
        t("hoist-block", "<div onclick=1><p>P1</p><p>P2</p></div><p>P3</p>");
        // textarea RCDATA entities
        t("ta-ent", "<textarea>&lt;b&gt; &amp; &#65;</textarea>");
        // table inside rejected div
        t("table-reject", "<div onclick=1><table><tr><td>a</td></tr></table></div>");
        // script safelisted contains markup-like data
        Safelist sls = Safelist.relaxed().addTags("script");
        String o = Jsoup.clean("<p>x</p><script>if(a<b && c>d){<x>}</script>", sls);
        System.out.println("safe-script o1=[" + o.replace("\n","\\n") + "]");
        System.out.println("safe-script o2=[" + Jsoup.clean(o, sls).replace("\n","\\n") + "]");
        System.out.println("reparsed script text=[" + Jsoup.parse(o).select("script").data().replace("\n","\\n") + "]");
        // entity in attribute
        t("attr-ent", "<a href='http://a/?a=1&amp;b=2' title='x&amp;y'>L</a>");
        // nbsp
        t("nbsp", "<p>a&nbsp;b &nbsp; c</p>");
    }
}
