import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.Safelist;
public class Final {
    static int fail=0;
    static void ok(boolean cond, String msg){ if(!cond){fail++; System.out.println("FAIL: "+msg);} }
    public static void main(String[] a){
        Safelist sl = Safelist.relaxed().addTags("pre","code","textarea").addAttributes(":all","class","id");

        // 1 pre/code/textarea whitespace, literals, entities survive clean+serialize+reparse
        String[] ws = {
            "<pre>  a\t\nb\n  &lt;x&gt; &amp;amp; </pre>",
            "<code>x = 1   \n\tline2 &lt;i&gt; &amp;amp;</code>",
            "<textarea>l1\n  l2 &lt;b&gt; &amp; &#65;</textarea>",
            "<pre><code>  nested\n  ws\t</code></pre>"
        };
        for (String in : ws) {
            String o = Jsoup.clean(in, sl);
            Document d = Jsoup.parseBodyFragment(o);
            String o2 = Jsoup.clean(d.body().html(), sl);
            ok(o.equals(o2), "ws idempotent: "+o.replace("\n","\\n"));
            ok(Jsoup.parseBodyFragment(o).body().html().equals(Jsoup.parseBodyFragment(o2).body().html()), "ws reparse "+o);
            // literal angle brackets / entities not interpreted as tags
            ok(o.contains("&lt;") && !o.contains("<x>") && !o.contains("<i>") && !o.contains("<b>"), "literals "+o);
        }

        // 2 dangerous wrapper hoists safe descendants in order, no dup/loss
        String h = Jsoup.clean("<div onclick='x()'>safe <a href='http://e.com'>link</a> tail</div>", sl);
        ok(h.contains("safe") && h.contains("link") && h.contains("tail"), "hoist keeps text");
        ok(h.indexOf("safe")<h.indexOf("link") && h.indexOf("link")<h.indexOf("tail"), "hoist order");
        ok(!h.toLowerCase().contains("onclick"), "event attr gone");

        // 3 script data stays text even with safe-looking markup
        String s = Jsoup.clean("<p>b</p><script>var a='<b>x</b>';</script><p>a</p>", sl);
        ok(s.contains("<p>b</p>") && s.contains("<p>a</p>") && !s.contains("<script"), "script removed, order kept");
        Safelist sls = Safelist.relaxed().addTags("script");
        String ss = Jsoup.clean("<script>if(a<b){'<img src=x onerror=1>'}</script>", sls);
        ok(ss.contains("&lt;img") || ss.contains("<img src=x onerror=1>"), "script data as-is");
        Document sd = Jsoup.parseBodyFragment(ss);
        String scriptData = sd.selectFirst("script").data();
        ok(scriptData.contains("<img src=x onerror=1>") && sd.select("img").isEmpty(), "script markup inert: "+scriptData);

        // 4 attributes values stable across reparses
        String at = Jsoup.clean("<a href='http://e.com/?a=1&amp;b=2' class='c' title='t&amp;v'>L</a>", sl);
        ok(at.equals(Jsoup.clean(at, sl)), "attr idempotent");
        Document d1=Jsoup.parseBodyFragment(at);
        ok(d1.selectFirst("a").attr("href").equals("http://e.com/?a=1&b=2"), "attr href decoded once");
        ok(d1.selectFirst("a").attr("title").equals("t&v"), "attr title");

        // 5 entity decoded once
        String e = Jsoup.clean("&amp;amp; &lt;img src=x onerror=1&gt;", Safelist.none());
        ok(e.equals("&amp;amp; &lt;img src=x onerror=1&gt;"), "entity once: "+e);

        // 6 empty / all rejected / malformed
        for (String in : new String[]{"","   ","<script>x</script><style>y</style>","<<<></","\0\0"}) {
            String c1 = Jsoup.clean(in, sl);
            String c2 = Jsoup.clean(c1, sl);
            ok(c1.equals(c2), "stable malformed ["+in.replace("\n","\\n")+"] -> "+c1);
        }

        // 7 independent calls, different safelists no pollution
        String r = Jsoup.clean("<script>1</script><p>x</p>", Safelist.relaxed());
        String n = Jsoup.clean("<script>1</script><p>y</p>", Safelist.none());
        String r2 = Jsoup.clean("<script>1</script><p>x</p>", Safelist.relaxed());
        ok(r.equals(r2) && n.equals("y") && !r.equals(n), "no cross pollution");

        // 8 selectors still find same structure after reparse
        String t = Jsoup.clean("<div><p>P1</p><p>P2 <a href='http://e.com'>L</a></p></div>", sl);
        Document td1 = Jsoup.parseBodyFragment(t), td2 = Jsoup.parseBodyFragment(Jsoup.clean(t, sl));
        for (String sel : new String[]{"div","p","a","p a"})
            ok(td1.select(sel).size()==td2.select(sel).size() && td1.select(sel).outerHtml().equals(td2.select(sel).outerHtml()), "selector "+sel);

        // 9 no extra visible chars between block content / inline
        String ab = Jsoup.clean("<a href='http://a/'>A</a><script>x</script><a href='http://b/'>B</a>", sl);
        ok(Jsoup.parseBodyFragment(ab).body().text().equals("AB"), "no invented space: "+Jsoup.parseBodyFragment(ab).body().text());

        // 10 unsafe scheme attrs dropped, safe ones kept
        String js = Jsoup.clean("<a href='javascript:alert(1)' class='ok'>x</a>", sl);
        ok(!js.contains("javascript"), "js scheme dropped: "+js);
        ok(js.contains("class=\"ok\""), "safe attr kept");

        // 11 whitespace flanked rejected node merges
        String w = Jsoup.clean("<p>x</p> \n <script>y</script> <p>z</p>", Safelist.none());
        ok(w.equals(Jsoup.clean(w, Safelist.none())) && w.equals("x z"), "ws merge: ["+w.replace("\n","\\n")+"]");

        // 12 nofollow stable on smuggled href
        String nf = Jsoup.clean("<a href='java%73cript:1'>x</a>", "https://example.com/", Safelist.basic());
        ok(nf.equals("<a rel=\"nofollow\">x</a>") && nf.equals(Jsoup.clean(nf, "https://example.com/", Safelist.basic())), "nofollow: "+nf);

        System.out.println(fail==0 ? "ALL PASS" : fail+" FAILURES");
    }
}
